class Solution:

	def minCost(self, N, cost):
		for i in range(1, len(cost)):
			for j in range(len(cost[0])):
				curr_min = float('inf')
				for k in range(3):
					if j != k:
						curr_min = min(curr_min, cost[i - 1][k])
				cost[i][j] += curr_min
		ans = float('inf')
		for i in range(3):
			ans = min(ans, cost[-1][i])
		return ans
